function renderPicker(){const list=$("[data-picker-list]"),needle=$("[data-search]").value.trim().toLocaleLowerCase("pt-BR");list.replaceChildren();const shown=pickerItems.filter(entry=>{const text=[entry.title,entry.fileName,entry.artist,entry.category,entry.subcategory].filter(Boolean).join(" ").toLocaleLowerCase("pt-BR");return !needle||text.includes(needle)});for(const entry of shown){const button=document.createElement("button");button.type="button";button.className="carimbo-picker-row";button.dataset.fileId=String(entry.id);const label=document.createElement("span");label.textContent=entry.title||entry.fileName||"Áudio";const meta=document.createElement("small");const seconds=Number(entry.duration);meta.textContent=[entry.category,Number.isFinite(seconds)?clock(seconds):""].filter(Boolean).join(" · ");button.append(label,meta);button.onclick=()=>void addLibraryFile(entry);list.append(button)}$("[data-picker-status]").textContent=shown.length?shown.length+" arquivo(s)"+(pickerItems.length<500?"":" carregado(s)"):"Nenhum arquivo encontrado."; $("[data-more]").hidden=!pickerHasMore||pickerBusy}
async function loadPicker(reset=true){if(pickerBusy)return;if(reset){pickerOffset=0;pickerItems=[];pickerHasMore=false}pickerBusy=true;$("[data-picker-status]").textContent="Carregando arquivos…";$("[data-more]").hidden=true;try{const params=new URLSearchParams({limit:"500",offset:String(pickerOffset)});if(pickerSource==="catalog"&&$("[data-category]").value)params.set("category",$("[data-category]").value);const response=await fetch("/api/library?"+params.toString(),{credentials:"include",cache:"no-store"});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||"Não foi possível consultar os arquivos.");const batch=Array.isArray(data.items)?data.items:[];pickerItems.push(...batch);pickerOffset+=batch.length;pickerHasMore=batch.length===500;renderPicker();if(!pickerItems.length)$("[data-picker-status]").textContent="Nenhum áudio disponível nesta origem."}catch(error){$("[data-picker-status]").textContent=error.message;pickerHasMore=false}finally{pickerBusy=false;$("[data-more]").hidden=!pickerHasMore}}
function openPicker(target="overlay"){pickerTarget=target;$(".carimbo-picker-heading strong").textContent=target==="main"?"Selecionar música":"Adicionar carimbo";$("[data-local]").hidden=target==="main";const picker=$("[data-picker]");picker.hidden=false;pickerSource="catalog";$("[data-category]").hidden=false;$("[data-category]").value="";$("[data-search]").value="";panel.querySelectorAll("[data-source]").forEach(button=>button.classList.toggle("active",button.dataset.source==="catalog"));void loadPicker(true)}
async function addLibraryFile(entry){const target=pickerTarget;if(!entry||busy||(target==="overlay"&&!main))return;stop();const token=session,loadToken=++audioLoad;tell("Carregando "+(entry.title||entry.fileName||"áudio")+"…");try{const response=await fetch("/api/library/"+encodeURIComponent(entry.id)+"/audio"+(target==="main"?"?carimboOriginal=1":""),{credentials:"include",cache:"no-store"});if(!response.ok)throw Error("Não foi possível abrir esse áudio (HTTP "+response.status+").");const blob=await response.blob(),buffer=await ctx().decodeAudioData(await blob.arrayBuffer());if(token!==session||loadToken!==audioLoad)return;if(target==="main"){main=buffer;item=entry;position=0;overlay=null;overlayFile=null;overlayName="";$("[data-offset]").max=String(buffer.duration);$("[data-offset]").value="0";$("[data-main-title]").textContent=title(entry);$("#carimbo-name").value=title(entry)}else{overlay=buffer;overlayFile=blob;overlayName=entry.title||entry.fileName||"Carimbo";$("[data-overlay-title]").textContent=overlayName}$("[data-picker]").hidden=true;draw();tell(target==="main"?(panel.dataset.editorMode==="voice"?"Música carregada. Toque em Gravar voz.":"Música carregada. Adicione o carimbo."):"Carimbo adicionado. Arraste a onda verde para ajustar a entrada.")}catch(error){if(token===session&&loadToken===audioLoad)tell(error.message)}}

panel.querySelectorAll("[data-source]").forEach(button=>button.addEventListener("click",()=>{pickerSource=button.dataset.source;panel.querySelectorAll("[data-source]").forEach(tab=>tab.classList.toggle("active",tab===button));$("[data-category]").hidden=pickerSource!=="catalog";void loadPicker(true)}));
$("[data-category]").addEventListener("change",()=>void loadPicker(true));$("[data-search]").addEventListener("input",renderPicker);$("[data-more]").addEventListener("click",()=>void loadPicker(false));$("[data-picker-close]").addEventListener("click",()=>{$("[data-picker]").hidden=true});$("[data-local]").addEventListener("click",()=>{$("[data-picker]").hidden=true;$("[data-file]").click()});
const close=()=>{if(busy)return;session++;audioLoad++;if(voiceRecorder?.state==="recording")voiceRecorder.stop();voiceStream?.getTracks().forEach(track=>track.stop());voiceRecorder=null;voiceStream=null;stop();$("[data-picker]").hidden=true;panel.hidden=true};$(".carimbo-close").onclick=close;
panel.querySelectorAll("[data-editor-tab]").forEach(button=>button.addEventListener("click",()=>setEditorMode(button.dataset.editorTab)));
$("[data-intro-set]").onclick=()=>{if(!main)return;const current=playing?position+ctx().currentTime-started:position;setIntroPoint(current);tell("Introdução marcada em "+clock(introPoint)+".")};$("[data-select-main]").onclick=()=>openPicker("main");
function nudgeIntro(delta){if(!main||busy||panel.dataset.editorMode!=="intro")return;setIntroPoint(Number((introPoint+delta).toFixed(2)));tell("Introdução ajustada para "+introPoint.toFixed(2).replace(".",",")+" s.")}
$("[data-intro-minus]").onclick=()=>nudgeIntro(-0.01);
$("[data-intro-plus]").onclick=()=>nudgeIntro(0.01);
$("[data-intro-return]").onclick=()=>{if(!main||busy||panel.dataset.editorMode!=="intro")return;stop();position=Math.max(0,Math.min(main.duration,introPoint));paintTime(position);if(position<main.duration)void play().catch(error=>tell(error.message))};
$("[data-rewind]").onclick=()=>{if(!main||busy)return;stop();position=0;paintTime(0);void play().catch(error=>tell(error.message))};
$("[data-remove]").onclick=()=>{stop();overlay=null;overlayFile=null;overlayName="";$(".carimbo-clip").hidden=true;$("[data-overlay-title]").textContent="Adicione o áudio do carimbo";draw();tell("Carimbo removido desta edição.")};
for(const [selector,input,delta] of [["[data-main-down]","[data-main-gain]",-5],["[data-main-up]","[data-main-gain]",5],["[data-overlay-down]","[data-overlay-gain]",-5],["[data-overlay-up]","[data-overlay-gain]",5]])$(selector).onclick=()=>{const control=$(input);control.value=String(Math.max(0,Math.min(100,(Number(control.value)||0)+delta)));control.dispatchEvent(new Event("input",{bubbles:true}))};
$("[data-record]").onclick=async()=>{if(!main||busy)return;if(voiceRecorder?.state==="recording"){voiceRecorder.stop();return}const token=session,loadToken=audioLoad;let stream=null;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error("Gravação de voz não suportada neste dispositivo.");stream=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==session||loadToken!==audioLoad){stream.getTracks().forEach(track=>track.stop());return}voiceStream=stream;const chunks=[],recorder=new MediaRecorder(stream);voiceRecorder=recorder;recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data)};recorder.onstop=async()=>{stream.getTracks().forEach(track=>track.stop());if(voiceRecorder===recorder){voiceRecorder=null;voiceStream=null;$("[data-record]").textContent="● Gravar voz"}if(token!==session||loadToken!==audioLoad)return;try{const blob=new Blob(chunks,{type:recorder.mimeType||"audio/webm"}),buffer=await ctx().decodeAudioData(await blob.arrayBuffer());if(token!==session||loadToken!==audioLoad)return;overlay=buffer;overlayFile=blob;overlayName="Voice Track";$("[data-overlay-title]").textContent=overlayName;draw();tell("Voice Track gravado. Ajuste a entrada e salve a edição.")}catch(error){tell("Não foi possível abrir a gravação: "+error.message)}};recorder.start();$("[data-record]").textContent="■ Parar gravação";tell("Gravando Voice Track…")}catch(error){stream?.getTracks().forEach(track=>track.stop());if(token===session&&loadToken===audioLoad)tell(error.message)}};
$("[data-cancel]").onclick=close;$("[data-add]").onclick=()=>{if(!main){tell("Aguarde o áudio principal carregar.");return}openPicker()};$("[data-file]").onchange=e=>{void addFile(e.target.files[0]);e.target.value=""};$("[data-play]").onclick=()=>void play().catch(error=>tell(error.message));$("[data-stop]").onclick=()=>{stop();position=0;paintTime(0)};$("[data-save]").onclick=()=>void save();
for(const name of ["offset","main-gain","overlay-gain","fade-in","fade-out"]){$("[data-"+name+"]").addEventListener("input",()=>{stop();if(name==="offset"&&main){$("[data-offset]").value=String(Math.max(0,Math.min(main.duration,Number($("[data-offset]").value)||0)));if(panel.dataset.editorMode==="intro")setIntroPoint($("[data-offset]").value);}$("[data-main-value]").textContent=$("[data-main-gain]").value+"%";$("[data-overlay-value]").textContent=$("[data-overlay-gain]").value+"%";draw()})}
function setZoom(value){const viewport=$(".carimbo-scroll"),oldWidth=$(".carimbo-timeline").getBoundingClientRect().width,center=oldWidth?(viewport.scrollLeft+viewport.clientWidth/2)/oldWidth:0;zoom=Math.max(1,Math.min(8,Number(value)||1));$("[data-zoom]").value=String(zoom);$("[data-zoom-value]").textContent=String(zoom).replace(".",",")+"×";$("[data-pan]").hidden=zoom===1;draw();viewport.scrollLeft=Math.max(0,center*$(".carimbo-timeline").getBoundingClientRect().width-viewport.clientWidth/2);syncPan()}
function syncPan(){const viewport=$(".carimbo-scroll"),max=viewport.scrollWidth-viewport.clientWidth;$("[data-pan]").value=String(max>0?viewport.scrollLeft/max*1000:0);positionCursorBubble()}
$("[data-zoom]").oninput=e=>setZoom(e.target.value);function setHeight(value){heightZoom=Math.max(1,Math.min(5,Number(value)||1));localStorage.setItem("playmaster-air-carimbo-height-zoom",String(heightZoom));$("[data-height]").value=String(heightZoom);$("[data-height-value]").textContent=String(heightZoom).replace(".",",")+"×";draw()}$("[data-height]").oninput=e=>setHeight(e.target.value);$("[data-height-up]").onclick=()=>setHeight(heightZoom+.25);$("[data-height-down]").onclick=()=>setHeight(heightZoom-.25);$("[data-zoom-in]").onclick=()=>setZoom(zoom+.25);$("[data-zoom-out]").onclick=()=>setZoom(zoom-.25);$("[data-pan]").oninput=e=>{const viewport=$(".carimbo-scroll");viewport.scrollLeft=(viewport.scrollWidth-viewport.clientWidth)*Number(e.target.value)/1000};$(".carimbo-scroll").addEventListener("scroll",syncPan);
let drag=null;$(".carimbo-clip").onpointerdown=e=>{if(!main||busy)return;e.preventDefault();e.stopPropagation();stop();drag={id:e.pointerId,x:e.clientX,offset:Number($("[data-offset]").value)||0};e.currentTarget.setPointerCapture(e.pointerId)};$(".carimbo-clip").onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;const width=$(".carimbo-secondary").getBoundingClientRect().width;$("[data-offset]").value=String(Math.max(0,Math.min(main.duration-.01,drag.offset+(e.clientX-drag.x)/width*main.duration)).toFixed(1));draw()};$(".carimbo-clip").onpointerup=$(".carimbo-clip").onpointercancel=()=>{drag=null};$(".carimbo-timeline").onpointerdown=e=>{if(!main||e.target.closest(".carimbo-clip")||busy)return;stop();const rect=$(".carimbo-timeline").getBoundingClientRect();position=Math.max(0,Math.min(main.duration,(e.clientX-rect.left)/rect.width*main.duration));paintTime(position)};
let moving=null;$("header").onpointerdown=e=>{if(e.target.closest("button"))return;const r=panel.getBoundingClientRect();panel.style.transform="none";panel.style.left=r.left+"px";panel.style.top=r.top+"px";moving={x:e.clientX,y:e.clientY,left:r.left,top:r.top};e.currentTarget.setPointerCapture(e.pointerId)};$("header").onpointermove=e=>{if(!moving)return;panel.style.left=Math.max(0,Math.min(innerWidth-panel.offsetWidth,moving.left+e.clientX-moving.x))+"px";panel.style.top=Math.max(0,Math.min(innerHeight-36,moving.top+e.clientY-moving.y))+"px"};$("header").onpointerup=$("header").onpointercancel=()=>{moving=null};window.addEventListener("resize",draw);
const tool=document.querySelector(".toolbar .tool[data-carimbo-tool]");if(tool){tool.removeAttribute("aria-disabled");tool.tabIndex=0;tool.setAttribute("role","button");tool.setAttribute("aria-label","Abrir Editor de áudio");tool.addEventListener("click",event=>{event.preventDefault();window.dispatchEvent(new CustomEvent("playmaster:editor-open-request"))});tool.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();window.dispatchEvent(new CustomEvent("playmaster:editor-open-request"))}})}
